import com.sap.gateway.ip.core.customdev.util.Message;import java.time.LocalDate;import java.time.format.DateTimeFormatter;import java.time.temporal.TemporalAdjusters;def Message processData(Message message) {    // Body    def pMap         = message.getProperties();    StringBuffer str = new StringBuffer();    // Properties     def UserId                = pMap.get("UserId");    def WorkerClass           = pMap.get("WorkerClass");    def country               = pMap.get("countryOfCompany");    def Status                = pMap.get("Status");    def enablePayloadLogging  = pMap.get("enablePayloadLogging");    def messageLog = messageLogFactory.getMessageLog(message);    // Calculate current month end date in yyyy-MM-dd format    def today = LocalDate.now();    def currentMonthEnd = today.with(TemporalAdjusters.lastDayOfMonth());    def dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");    def currentMonthEndStr = currentMonthEnd.format(dateFormatter);        // Calculate prior month end date in yyyyMMdd format    def priorMonth = today.minusMonths(1);    def priorMonthEnd = priorMonth.with(TemporalAdjusters.lastDayOfMonth());    def priorMonthEndFormatter = DateTimeFormatter.ofPattern("yyyyMMdd");    def priorMonthEndStr = priorMonthEnd.format(priorMonthEndFormatter);       // Build filter    if(UserId && UserId.trim().length()>0){        UserId = UserId.trim().replace(",","','");        str.append(" (personIdExternal in '"+UserId+"')");            if(Status && Status.trim().length()>0){            Status = Status.trim().replace(",","','");            str.append(" and (jobInfoNav/emplStatusNav/externalCode in '"+Status+"')");        }    }    else {        if(Status && Status.trim().length()>0){            Status = Status.trim().replace(",","','");            str.append(" (jobInfoNav/emplStatusNav/externalCode in '"+Status+"')");        }    }    if(country.trim().length()>0){        country = country.trim().replace(",","','");        str.append(" and (jobInfoNav/countryOfCompany like '"+country+"')");    }    if(WorkerClass && WorkerClass.trim().length()>0){        WorkerClass = WorkerClass.trim().replace(",","','");        str.append(" and not (jobInfoNav/employeeClassNav/externalCode in '"+WorkerClass+"')");    }                  str.append(" and (hiringNotCompleted eq false)");    // setProperty    message.setProperty("QueryParam1", str.toString());    message.setProperty("CurrentMonthEndDate", currentMonthEndStr);    message.setProperty("PriorMonthEndDate", priorMonthEndStr); // <-- YYYYMMDD format    message.setHeader("enablePayloadLogging", enablePayloadLogging);    messageLog.addAttachmentAsString("Active Employees Filter", str.toString(), "text/xml");    return message;}